#pragma once
#include "raylib.h"
enum class BlockType{Air,Grass,Dirt,Stone,OakLog,Leaves,Planks,CraftingTable,Stick,Pickaxe,Axe,Sword};
inline const char* BlockName(BlockType b){switch(b){case BlockType::Grass:return "Grass";case BlockType::Dirt:return "Dirt";case BlockType::Stone:return "Stone";case BlockType::OakLog:return "Oak Log";case BlockType::Leaves:return "Leaves";case BlockType::Planks:return "Planks";case BlockType::CraftingTable:return "Crafting Table";case BlockType::Stick:return "Stick";case BlockType::Pickaxe:return "Pickaxe";case BlockType::Axe:return "Axe";case BlockType::Sword:return "Sword";default:return "Empty";}}
inline Color BlockColor(BlockType b){switch(b){case BlockType::Grass:return Color{92,168,72,255};case BlockType::Dirt:return Color{132,91,58,255};case BlockType::Stone:return Color{120,124,130,255};case BlockType::OakLog:return Color{117,79,45,255};case BlockType::Leaves:return Color{58,139,61,255};case BlockType::Planks:return Color{190,143,82,255};case BlockType::CraftingTable:return Color{155,99,51,255};default:return MAGENTA;}}
